/* Apple Liquid Glass for T3 Code */ :root{--ml:4px;--mr:8px;--g:#e4e4e9;--p:#f7f7fa;--s:#f4f4f7;--b:#ffffffeb;--a:#006be0;--sh:inset 0 1px 0 #fff,0 4px 20px -8px #0000001a,0 0 0 .5px #0000000f;--shf:0 4px 20px -8px #0000001a,0 0 0 .5px #0000000f;--bf10:blur(10px) saturate(180%) brightness(1.08);--bf12:blur(12px) saturate(185%) brightness(1.08);--bf14:blur(14px) saturate(185%) brightness(1.08);--cbg:radial-gradient(64% 48% at 10% 2%,#60aeff21,#0000 68%),radial-gradient(52% 44% at 90% 8%,#b09cff1a,#0000 70%),radial-gradient(50% 40% at 84% 88%,#5ad6e814,#0000 70%),radial-gradient(58% 44% at 22% 96%,#6cb8ff1a,#0000 72%);--sbg:radial-gradient(125% 42% at 14% 4%,#60aeff1f,#0000 72%),radial-gradient(115% 42% at 86% 94%,#b09cff18,#0000 74%),linear-gradient(#ffffff94,#ffffff57);--hbg:radial-gradient(45% 180% at 10% 0%,#60aeff21,#0000 72%),radial-gradient(40% 180% at 90% 0%,#b09cff1a,#0000 74%),linear-gradient(#ffffffa6,#ffffff5c);--ovbg:linear-gradient(155deg,#ffffffb8,#ffffff70 54%,#ffffff8f);--ovb:#ffffffeb;--ovsh:inset 0 2px 0 #fff,inset 1.5px 0 0 #ffffffdb,inset 0 -1px 0 #0000000a,0 4px 14px #00000014,0 22px 56px -12px #0003,0 0 0 .5px #00000012}
.dark{--g:#070709;--p:#111115;--s:#111115;--b:#ffffff1a;--a:#409cff;--sh:inset 0 1px 0 #ffffff29,0 10px 30px -14px #000000b2;--shf:0 10px 30px -14px #000000b2;--cbg:radial-gradient(64% 48% at 12% 4%,#388aff16,#0000 68%),radial-gradient(52% 44% at 90% 10%,#8472f512,#0000 70%),radial-gradient(50% 40% at 84% 88%,#2cc2e00e,#0000 70%),radial-gradient(58% 44% at 22% 96%,#3482f511,#0000 72%);--sbg:radial-gradient(125% 42% at 14% 4%,#388aff14,#0000 72%),radial-gradient(115% 42% at 86% 94%,#8472f511,#0000 74%),linear-gradient(#ffffff09,#ffffff03);--hbg:radial-gradient(45% 180% at 12% 0%,#388aff16,#0000 72%),radial-gradient(40% 180% at 90% 0%,#8472f512,#0000 74%),linear-gradient(#ffffff0e,#ffffff04);--ovbg:linear-gradient(155deg,#ffffff1f,#16161a6b 50%,#ffffff0f);--ovb:#ffffff38;--ovsh:inset 0 1.5px 0 #ffffff7a,inset 1.5px 0 0 #ffffff2e,inset 0 -1px 0 #ffffff1f,inset 0 0 26px #ffffff0a,0 4px 14px #0006,0 26px 64px -14px #000000c2}
body{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display",system-ui,sans-serif!important;letter-spacing:-.008em;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;background:var(--g)!important}
pre,code{font-family:"SF Mono",ui-monospace,"JetBrains Mono Variable","JetBrains Mono",Menlo,Consolas,monospace!important;letter-spacing:normal}
::selection{background:#007aff33}
.dark ::selection{background:#0a84ff57}
svg.lucide{stroke-width:1.65;stroke-linecap:round;stroke-linejoin:round}
