[data-slot=sidebar-inner]{margin:8px 4px 8px 8px!important;width:calc(100% - 12px)!important;height:calc(100% - 16px)!important;border-radius:16px!important;overflow:hidden!important;background-color:var(--s)!important;background-image:var(--sbg)!important;background-repeat:no-repeat!important;background-size:100% 100%!important;border:1px solid var(--b)!important;box-shadow:var(--sh)!important;backdrop-filter:none!important;transition:background .18s ease,box-shadow .18s ease;.dark &{box-shadow:inset 0 1px 0 #ffffff29,inset 1px 0 0 #ffffff0f,0 10px 30px -14px #000000b2!important}}
[data-slot=sidebar][data-side=right] [data-slot=sidebar-inner]{margin:8px 8px 8px 4px!important}
[data-thread-item]{border-radius:12px!important;font-weight:400!important;color:#1d1d1fcc;transition:.16s ease!important;&:hover{background:#ffffff8c!important;box-shadow:inset 0 1px 0 #ffffffe6!important;color:#1d1d1f}
&:is([data-active=true],[aria-current=page]){background:linear-gradient(#ffffffe6,#ffffffa8)!important;color:#1d1d1f;font-weight:500!important;box-shadow:inset 0 1.5px 0 #fff,inset 1px 0 0 #ffffffd9,0 3px 12px -4px #0000001f,0 0 0 .5px #0000000d!important}
.dark &{color:#f5f5f7cc;&:hover{background:#ffffff13!important;box-shadow:inset 0 .5px 0 #ffffff29!important;color:#fff}
&:is([data-active=true],[aria-current=page]){background:linear-gradient(#ffffff29,#ffffff14)!important;color:#fff;box-shadow:inset 0 1px 0 #ffffff5c,inset 1px 0 0 #ffffff24,inset 0 -1px 0 #ffffff14,0 3px 12px -4px #00000073!important}}}
[data-slot=project-monogram]{border-radius:7px!important;overflow:hidden;box-shadow:inset 0 1px 0 #fffffff2,0 2px 8px -3px #0000001f;& svg{border-radius:7px!important}
.dark &{box-shadow:inset 0 1px 0 #ffffff57,0 2px 8px -2px #00000073}}
[data-chat-header]{margin:8px var(--mr) 0 var(--ml)!important;width:calc(100% - var(--ml) - var(--mr))!important;border-radius:16px 16px 0 0!important;background-color:var(--p)!important;background-image:var(--hbg)!important;border:1px solid var(--b)!important;border-bottom:1px solid #0000000f!important;box-shadow:inset 0 1px 0 #fff!important;backdrop-filter:var(--bf10);.dark &{border-bottom-color:#ffffff14!important;box-shadow:inset 0 1px 0 #ffffff29!important}
& [data-slot=button]{border-radius:999px!important;background:#ffffff7a;box-shadow:inset 0 1px 0 #fffffff5,0 1px 3px #0000000f;&:is(:not(:disabled):hover,[aria-pressed=true],[data-popup-open],[aria-expanded=true]){background:linear-gradient(#ffffffeb,#ffffffb2)!important;box-shadow:inset 0 1.5px 0 #fff,0 4px 12px -4px #00000024,0 0 0 .5px #0000000d!important}
