:is([data-chat-header] [data-slot=button],[data-chat-composer-form] [data-slot=button]:not([type=submit])):not(:disabled):active{transform:scale(.95)}
.chat-markdown{line-height:1.625;& :is(strong,b){font-weight:560}
& :is(h1,h2,h3,h4,h5,h6){font-weight:600;letter-spacing:-.02em;line-height:1.25}
& a{color:var(--a);text-decoration:none;&:hover{text-decoration:underline;text-decoration-thickness:from-font;text-underline-offset:.18em}}
& hr{border-color:#00000017;.dark &{border-color:#ffffff1a}}
& blockquote{border-radius:0 12px 12px 0;padding:.45rem .85rem;background:#ffffff80;border-left:2px solid #00000038;color:#636366;.dark &{background:#ffffff0a;border-left-color:#ffffff47;color:#a1a1a6}}
& table{border-collapse:collapse}
& th{border-bottom:1px solid #00000029!important;color:#636366;font-weight:500;.dark &{border-bottom-color:#ffffff2e!important;color:#a1a1a6}}
& td{border-bottom:1px solid #00000014!important;.dark &{border-bottom-color:#ffffff14!important}}
& tbody tr:last-child td{border-bottom:0!important}
& :not(pre)>code{border-radius:7px!important;padding:.1rem .375rem!important;background:#ffffffa6!important;border:1px solid #00000014!important;.dark &{background:#ffffff13!important;border-color:#ffffff1a!important}}}
.chat-markdown-codeblock{border-radius:16px!important;overflow:hidden;background:linear-gradient(160deg,#ffffffad,#ffffff70)!important;border:1px solid #ffffffe6!important;box-shadow:inset 0 1.5px 0 #fff,0 8px 22px -12px #0000001a,0 0 0 .5px #0000000d!important;backdrop-filter:var(--bf10);& pre{background:none!important;border:0!important}
.dark &{background:linear-gradient(160deg,#ffffff0f,#ffffff05 45%,#ffffff09)!important;border-color:#ffffff1f!important;box-shadow:inset 0 1px 0 #fff3,inset 1px 0 0 #ffffff14,0 10px 26px -14px #0000008c!important}}
[data-user-message-bubble]{border-radius:20px!important;line-height:1.625!important;background:linear-gradient(150deg,#ffffffb8,#ffffff6b 55%,#ffffff8a)!important;border:1px solid #ffffffeb!important;color:#1d1d1f!important;box-shadow:inset 0 1.5px 0 #fff,inset 1px 0 0 #ffffffd6,0 10px 26px -12px #0000001f,0 0 0 .5px #0000000d!important;backdrop-filter:var(--bf10);& :not(pre)>code{background:#0000000f!important;border-color:#00000014!important}
& .chat-markdown-codeblock{border-radius:12px!important;backdrop-filter:none!important;box-shadow:none!important;& pre{background:none!important}}
& :is(pre,.chat-markdown-codeblock){background:#0000000a!important}
.dark &{background:linear-gradient(150deg,#ffffff1f,#ffffff0a 48%,#ffffff12)!important;border-color:#ffffff2e!important;color:#f5f5f7!important;box-shadow:inset 0 1px 0 #ffffff61,inset 1px 0 0 #ffffff26,inset 0 -1px 0 #ffffff1a,0 10px 28px -12px #00000085!important;& :not(pre)>code{background:#ffffff1f!important;border-color:#ffffff29!important}
& :is(pre,.chat-markdown-codeblock){background:#00000057!important}}}
[data-chat-composer-form]{background:none!important;border-radius:inherit;& [data-slot=button]:not([type=submit]){border-radius:999px!important;&:is(:not(:disabled):hover,[data-popup-open],[aria-expanded=true]){background:linear-gradient(#ffffffe0,#ffffff94)!important;box-shadow:inset 0 1px 0 #fff,0 2px 8px -3px #0000001a;.dark &{background:linear-gradient(#ffffff29,#ffffff14)!important;box-shadow:inset 0 1px 0 #ffffff52}}}
& button[type=submit]{background:linear-gradient(#339bff,#007aff 52%,#005dc9)!important;color:#fff!important;border:1px solid #ffffff7a!important;border-radius:999px!important;box-shadow:inset 0 1.5px 0 #ffffffad,inset 0 -1px 1px #00287833,0 5px 16px -4px #007aff7a!important;transition:transform .17s ease,filter .15s ease,box-shadow .17s ease!important;&:not(:disabled):hover{transform:scale(1.06);filter:brightness(1.08)}
&:not(:disabled):active{transform:scale(.94)}
&:disabled{background:linear-gradient(#ffffffb8,#ffffff6b)!important;color:#0000005c!important;border-color:#ffffffe0!important;opacity:1!important;box-shadow:inset 0 1px 0 #fff,0 2px 6px #0000000f!important;transform:none!important}
.dark &{background:linear-gradient(#3ba3ff,#0a84ff 50%,#0064db)!important;border-color:#fff6!important;box-shadow:inset 0 1.5px 0 #ffffff9e,inset 0 -1px 1px #00287847,0 5px 18px -4px #0a84ff9e!important;&:disabled{background:linear-gradient(#ffffff24,#ffffff0f)!important;color:#ffffff75!important;border-color:#ffffff2e!important;box-shadow:inset 0 1px 0 #ffffff47!important}}}}
[data-slot=composer-host]{border-radius:22px!important;background:linear-gradient(155deg,#ffffffa8,#ffffff52 48%,#ffffff75)!important;border:1px solid #ffffffe6!important;box-shadow:inset 0 2px 0 #fff,inset 1.5px 0 0 #ffffffdb,inset 0 -1px 0 #0000000d,0 2px 8px #0000000f,0 16px 40px -12px #00000029,0 0 0 .5px #00000012!important;backdrop-filter:var(--bf12);transition:border-color .2s ease,box-shadow .22s ease,background .2s ease!important;&:focus-within{background:linear-gradient(155deg,#ffffffc7,#ffffff75 48%,#ffffff94)!important;border-color:#fff!important;box-shadow:inset 0 2px 0 #fff,inset 1.5px 0 0 #fffffff0,0 0 0 3px #007aff24,0 18px 44px -12px #0000002e!important}
.dark &{background:linear-gradient(155deg,#ffffff1c,#ffffff08 44%,#fff1)!important;border-color:#fff3!important;box-shadow:inset 0 1.5px 0 #ffffff70,inset 1px 0 0 #ffffff2e,inset 0 -1px 0 #ffffff1f,inset -1px 0 0 #ffffff14,inset 0 0 22px #ffffff09,0 2px 8px #00000052,0 20px 50px -14px #000000a6!important;&:focus-within{background:linear-gradient(155deg,#ffffff24,#ffffff0b 46%,#ffffff16)!important;border-color:#ffffff57!important;box-shadow:inset 0 1.5px 0 #ffffff94,inset 1px 0 0 #ffffff3d,inset 0 -1px 0 #ffffff29,inset 0 0 26px #ffffff0e,0 0 0 3px #ffffff12,0 22px 54px -14px #000000b8!important}}}
.composer-tiptap{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,sans-serif!important;line-height:1.625!important}
[data-thread-details-card]{border-radius:18px!important;overflow:hidden;background:linear-gradient(155deg,#ffffffa8,#ffffff5c)!important;border:1px solid #ffffffe6!important;box-shadow:inset 0 1.5px 0 #fff,0 10px 26px -10px #0000001f,0 0 0 .5px #0000000d!important;backdrop-filter:var(--bf12);.dark &{background:linear-gradient(155deg,#ffffff1a,#ffffff08 50%,#ffffff0e)!important;border-color:#ffffff29!important;box-shadow:inset 0 1px 0 #ffffff52,inset 1px 0 0 #ffffff1f,0 12px 30px -12px #0000008c!important}}
[data-thread-terminal-drawer]{background:#f7f7fac7!important;border-top:1px solid #ffffffe6!important;box-shadow:inset 0 1.5px 0 #fff,0 -4px 16px -6px #00000014!important;backdrop-filter:var(--bf14);.dark &{background:#111115b8!important;border-top-color:#ffffff1f!important;box-shadow:inset 0 1px 0 #ffffff24!important}}
[data-slot=button]{transition:.16s ease!important}
[data-slot=select-trigger]{border-radius:12px!important;background:#ffffff8f!important;border-color:#ffffffe0!important;box-shadow:inset 0 1px 0 #fff,0 2px 6px #0000000f;transition:.16s ease!important;&:is(:not(:disabled):hover,[data-popup-open],[aria-expanded=true]){background:#ffffffd6!important;border-color:#fff!important;box-shadow:inset 0 1.5px 0 #fff,0 3px 10px -2px #0000001a}
.dark &{background:#ffffff0f!important;border-color:#ffffff26!important;box-shadow:inset 0 1px 0 #ffffff38;&:is(:not(:disabled):hover,[data-popup-open],[aria-expanded=true]){background:#ffffff1c!important;border-color:#ffffff3d!important;box-shadow:inset 0 1px 0 #ffffff57}}}
:is([data-slot=button],[data-slot=select-trigger],[data-thread-item]):focus-visible{outline:2px solid var(--a)!important;outline-offset:2px}
[data-slot=switch]{background:#0000001a;box-shadow:inset 0 1px 2px #00000014;&:is([data-checked],[aria-checked=true]){background:linear-gradient(#339bff,#007aff)!important;border-color:#ffffff6b!important;box-shadow:inset 0 1px 0 #ffffff8a,0 3px 10px -2px #007aff66!important}
.dark &{background:#ffffff1f;box-shadow:inset 0 1px 0 #ffffff29;&:is([data-checked],[aria-checked=true]){background:linear-gradient(#3ba3ff,#0a84ff)!important;border-color:#ffffff57!important;box-shadow:inset 0 1px 0 #ffffff7a,0 3px 12px -2px #0a84ff94!important}}}
:is([data-slot=dialog-popup],[data-slot=popover-popup],[data-slot=menu-popup],[data-slot=tooltip-popup],[data-slot=select-trigger],[data-chat-header] [data-slot=button],[data-chat-composer-form] [data-slot=button])::before{border-radius:inherit!important;box-shadow:none!important}
[data-slot=dialog-popup]:not([class*=bg-transparent],[class*=border-0],[class*=border-none],[class*=border-transparent],[class*=shadow-none],[class*=inset-0],[class*=w-screen],[class*=h-screen]){border-radius:16px!important;background:var(--ovbg)!important;border:1px solid var(--ovb)!important;box-shadow:var(--ovsh)!important;backdrop-filter:var(--bf14)}
:is([data-slot=popover-popup],[data-slot=menu-popup]):not([class*=bg-transparent],[class*=border-0],[class*=border-none]){border-radius:14px!important;background:var(--ovbg)!important;border:1px solid var(--ovb)!important;box-shadow:var(--ovsh)!important;backdrop-filter:var(--bf12)}
[data-slot=tooltip-popup]{border-radius:10px!important;background:var(--ovbg)!important;border:1px solid var(--ovb)!important;box-shadow:inset 0 1.5px 0 #fff,0 10px 26px -8px #00000029,0 0 0 .5px #0000000f!important;backdrop-filter:var(--bf10);.dark &{box-shadow:inset 0 1px 0 #ffffff61,0 10px 28px -8px #0009!important}}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:none}
::-webkit-scrollbar-thumb{background:#00000029;border:2.5px solid #0000;background-clip:padding-box;border-radius:999px;&:hover{background:#00000047}}
.dark ::-webkit-scrollbar-thumb{background:#ffffff29;&:hover{background:#ffffff52}}
[data-slot=scroll-area-thumb]{border-radius:999px!important;background:#0000002e!important;transition:background-color .15s ease!important;&:hover{background:#00000052!important}
.dark &{background:#ffffff38!important;box-shadow:inset 0 .5px 0 #ffffff6b;&:hover{background:#ffffff61!important}}}
